const fs = require('fs');

function solve() {
    const buffer = fs.readFileSync(0);
    let offset = 0;

    function nextInt() {
        while (offset < buffer.length && buffer[offset] <= 32) {
            offset++;
        }
        if (offset >= buffer.length) return null;
        let res = 0;
        while (offset < buffer.length && buffer[offset] > 32) {
            res = res * 10 + (buffer[offset] - 48);
            offset++;
        }
        return res;
    }

    const N = nextInt();
    if (N === null) return;
    const K = nextInt();
    const T = nextInt();

    const P = new Int32Array(N + 1);
    for (let i = 1; i <= N; i++) {
        P[i] = nextInt();
    }

    const A = new Int32Array(K + 1);
    let kCount = 0;
    for (let i = 1; i <= N; i++) {
        const g = nextInt();
        if (g === 1) {
            kCount++;
            A[kCount] = i;
        }
    }

    const maxV = 9 * K;
    const stride = maxV + 1;
    const INF = 1000000000;

    // dp[j * stride + v]
    const dp = new Int32Array((K + 1) * stride);
    dp.fill(INF);
    dp[0] = 0;

    let currentMaxV = new Int32Array(K + 1);

    for (let i = 1; i <= N; i++) {
        const pi = P[i];
        const jMin = Math.max(1, K - N + i);
        const jMax = Math.min(i, K);

        for (let j = jMax; j >= jMin; j--) {
            const cost = Math.abs(A[j] - i);
            const prevRow = (j - 1) * stride;
            const currRow = j * stride;
            const prevLimit = currentMaxV[j - 1];

            for (let v = 0; v <= prevLimit; v++) {
                const prevCost = dp[prevRow + v];
                if (prevCost !== INF) {
                    const nv = v + pi;
                    const ncost = prevCost + cost;
                    if (ncost < dp[currRow + nv]) {
                        dp[currRow + nv] = ncost;
                    }
                }
            }
            if (prevLimit + pi > currentMaxV[j]) {
                currentMaxV[j] = Math.min(maxV, prevLimit + pi);
            }
        }
    }

    const finalRow = K * stride;
    let ans = 0;
    for (let v = maxV; v >= 0; v--) {
        if (dp[finalRow + v] <= T) {
            ans = v;
            break;
        }
    }

    console.log(ans);
}

solve();
